import {esc,uid,VERSION} from './core.js';import {BENCH_SUITES,validateBench,benchOutcome} from './qualification.js';
export function createQualificationUI(ui){const {button,tag,showDialog,field,area,selectField}=ui;const rows=()=>ui.project().benchRuns?.filter(r=>r.deviceId===ui.project().deviceId)||[];
 function view(){return `<div class="panel-body"><div class="row between wrap"><div><h3>Instrument qualification</h3><p class="muted smalltext spaced">Exact hardware, host and tool combinations; no compatibility inferred from simulations.</p></div><div class="row wrap">${button('Record bench run','bench-new','primary')}${button('Import bench report','bench-import','small','upload')}</div></div><div class="table-wrap spaced"><table><thead><tr><th>Suite / combination</th><th>Result</th><th>Method</th><th>Evidence</th></tr></thead><tbody>${rows().map(r=>`<tr><td>${esc(BENCH_SUITES[r.record.suite].label)}<span class="sub">${esc(r.record.environment.hardware||r.record.environment.os)}</span></td><td>${tag(benchOutcome(r.record))}</td><td>${esc(r.record.method)}</td><td>${button('Review','bench-review','small','',`data-id="${r.id}"`)} ${button('Original','evidence-detail','small','',`data-id="${r.evidenceId}"`)}</td></tr>`).join('')||'<tr><td colspan="4">No bench runs preserved for this device. The supplied debugger profiles remain unverified candidates.</td></tr>'}</tbody></table></div><p class="notice spaced">A pass applies only to the recorded combination and conditions. Imported reports are collector claims, not a signature or certification. Missing checks, missing context and simulations cannot establish physical compatibility.</p></div>`;}
 async function preserve(record,linked=[]){validateBench(record);const p=ui.project(),d=p.deviceId;if((p.benchRuns?.length||0)>=100)throw Error('This project retains up to 100 bench records.');const ev=await ui.evidenceFromFile(new File([JSON.stringify(record,null,2)],record.suite+'-bench.json',{type:'application/json'}),'Bench qualification','Recorded method: '+record.method,d);if(ui.project()!==p||p.deviceId!==d)throw Error('Project/device changed.');p.evidence.push(ev);p.benchRuns??=[];p.benchRuns.push({id:uid('bench'),deviceId:d,evidenceId:ev.id,evidenceIds:linked,record});ui.changed('Bench record preserved: '+benchOutcome(record)+'.');}
 function newRun(){showDialog('Choose bench procedure',`<label class="field">Suite<select name="suite">${Object.entries(BENCH_SUITES).map(([k,s])=>`<option value="${k}">${esc(s.label)}</option>`).join('')}</select></label>`,data=>{setTimeout(()=>editRun(data.get('suite')),0)},'Continue');}
 function editRun(suite){const p=ui.project(),d=p.deviceId,definition=BENCH_SUITES[suite];showDialog(definition.label+' acceptance',`<div class="form-grid">${field('Operator','operator','','text',true)}${field('Host OS / browser','os','','text',true)}${field('Board, probe / adapter and revisions','hardware','','text',true)}${field('Tool / probe firmware versions','tools','','text',true)}${area('Measured wiring, voltage, target firmware hash and test conditions','conditions','')}</div><div class="stack spaced">${Object.entries(definition.checks).map(([id,label])=>`<div class="baseline-row">${selectField(label,id,['not-run','passed','failed','blocked','inconclusive'],'not-run',true)}${field('Observed result / limitation','detail-'+id,'','text',true)}</div>`).join('')}</div><h3 class="spaced">Supporting evidence</h3>${ui.evidenceChecks()}<p class="notice spaced">Record actual observations. Physical passes need operator, hardware, tool versions, conditions and linked evidence. No step transmits to or operates a device from this form.</p>`,async data=>{if(ui.project()!==p||p.deviceId!==d)throw Error('Project/device changed.');const linked=data.getAll('evidenceIds'),record={format:'probe-bench-v1',id:uid('run'),version:VERSION,suite,method:definition.method,operator:data.get('operator').trim(),startedAt:new Date().toISOString(),endedAt:new Date().toISOString(),environment:Object.fromEntries(['os','hardware','tools','conditions'].map(k=>[k,data.get(k).trim()])),checks:Object.keys(definition.checks).map(id=>({id,status:data.get(id),detail:data.get('detail-'+id).trim()})),evidence:linked.map(id=>{const e=p.evidence.find(x=>x.id===id);return {evidenceId:id,name:e.title,sha256:e.hash}})};if(record.checks.some(c=>c.status==='passed'&&!c.detail))throw Error('Describe the observed result for each passed check.');await preserve(record,linked);},'Preserve bench record');}
 return {view,async action(name,id){if(!name.startsWith('bench-'))return false;if(name==='bench-new')newRun();else if(name==='bench-import')ui.pick('.json',async f=>{if(f.size>1024*1024)throw Error('Bench reports must be under 1 MiB.');await preserve(JSON.parse(await f.text()));});else if(name==='bench-review'){const r=rows().find(x=>x.id===id).record;showDialog('Bench qualification record',`<p>${esc(BENCH_SUITES[r.suite].label)} · ${tag(benchOutcome(r))}</p><pre class="code-preview spaced">${esc(JSON.stringify(r.environment,null,2))}</pre><div class="table-wrap spaced"><table><thead><tr><th>Check</th><th>Result</th><th>Observation</th></tr></thead><tbody>${r.checks.map(c=>`<tr><td>${esc(BENCH_SUITES[r.suite].checks[c.id]||c.id)}</td><td>${esc(c.status)}</td><td>${esc(c.detail)}</td></tr>`).join('')}</tbody></table></div>`);}return true;}};
}
